-- Mesen 2 --testrunner ROM scripts/trace_rom.lua; configuration is generated by trace_rom.py.
local base = RESEARCH_BASE
local cfg = dofile(base .. "trace_config.lua")
local frame = 0
local log = assert(io.open(base .. cfg.name .. ".log", "w"))
local trace = assert(io.open(base .. cfg.name .. ".trace", "w"))
local timerDmaCounts = {}
local paddingDmaCounts = {}
if cfg.timer_dma_start then
  local pending = false
  emu.addMemoryCallback(function() pending = true end,emu.callbackType.exec,cfg.timer_dma_start,cfg.timer_dma_start)
  emu.addMemoryCallback(function()
    if not pending then return end
    pending = false
    local s=emu.getState()
    local line=s['ppu.scanline']
    local blank=s['ppu.forcedBlank']
    local first=s['ppu.overscanMode'] and 240 or 225
    if not blank and (line<first or line>261) then
      log:write('FAIL timer DMA outside vblank: frame '..frame..' line '..line..'\n');log:flush()
      emu.stop(1)
    end
    local key=blank and 'forced blank' or tostring(line)
    timerDmaCounts[key]=(timerDmaCounts[key] or 0)+1
  end,emu.callbackType.exec,cfg.timer_dma_end,cfg.timer_dma_end)
  local paddingPending = false
  emu.addMemoryCallback(function()
    local x=emu.getState()['cpu.x']
    local function ram(off) return emu.read(x+off,emu.memType.snesWorkRam) end
    local source=ram(0x2A)+ram(0x2B)*256
    paddingPending=ram(0x2C)==0x9C and source>=0xF000 and source<0xFC00 and ram(0x2D)==64 and ram(0x2E)==0
  end,emu.callbackType.exec,0x808AF2,0x808AF2)
  emu.addMemoryCallback(function()
    if not paddingPending then return end
    paddingPending=false
    local s=emu.getState()
    local line=s['ppu.scanline']
    local blank=s['ppu.forcedBlank']
    local first=s['ppu.overscanMode'] and 240 or 225
    if not blank and (line<first or line>261) then
      log:write('FAIL padding DMA outside vblank: frame '..frame..' line '..line..'\n');log:flush()
      emu.stop(1)
    end
    local key=blank and 'forced blank' or tostring(line)
    paddingDmaCounts[key]=(paddingDmaCounts[key] or 0)+1
  end,emu.callbackType.exec,0x808AF5,0x808AF5)
end
local function dump(name, mem, size)
  local file = assert(io.open(base .. cfg.name .. "-" .. name .. ".bin", "wb"))
  local bytes = {}
  for i=0,size-1 do bytes[#bytes+1] = string.char(emu.read(i,mem)) end
  file:write(table.concat(bytes)); file:close()
end
local masks={b=0x8000,y=0x4000,select=0x2000,start=0x1000,up=0x0800,down=0x0400,left=0x0200,right=0x0100,a=0x0080,x=0x0040,l=0x0020,r=0x0010}
emu.addMemoryCallback(function(addr,value)
  addr=addr & 0xFFFF
  if addr>=0x421A then return 0 end
  local mask=0
  for _,ev in ipairs(cfg.inputs) do
    if frame>=ev[1] and frame<ev[2] then mask=mask | masks[ev[3]] end
  end
  if addr==0x4218 then return mask & 255 else return mask >> 8 end
end,emu.callbackType.read,0x804218,0x80421B)
emu.addEventCallback(function()
  local input = {a=false,b=false,x=false,y=false,start=false,select=false,up=false,down=false,left=false,right=false,l=false,r=false}
  for _,ev in ipairs(cfg.inputs) do
    if frame >= ev[1] and frame < ev[2] then input[ev[3]]=true end
  end
  emu.setInput(input,0)
  emu.setInput({a=false,b=false,x=false,y=false,start=false,select=false,up=false,down=false,left=false,right=false,l=false,r=false},1)
end,emu.eventType.inputPolled)
emu.addEventCallback(function()
  frame = frame+1
  for _,write in ipairs(cfg.writes) do
    if write[1]==frame then emu.write(write[2],write[3],emu.memType.snesWorkRam) end
  end
  if cfg.dumps[frame] then
    dump(frame.."-ram",emu.memType.snesWorkRam,131072)
    dump(frame.."-vram",emu.memType.snesVideoRam,65536)
    local f=assert(io.open(base..cfg.name.."-"..frame..".png","wb"));f:write(emu.takeScreenshot());f:close()
    for k,v in pairs(emu.getState()) do
      if string.sub(k,1,4)=="cpu." or string.sub(k,1,4)=="ppu." then log:write(frame.." "..k.."="..tostring(v).."\n") end
    end
    log:flush()
  end
  if frame>=cfg.frames then
    for line,count in pairs(timerDmaCounts) do log:write('PASS timer DMA end '..line..': '..count..'\n') end
    for line,count in pairs(paddingDmaCounts) do log:write('PASS padding DMA end '..line..': '..count..'\n') end
    trace:close(); log:close(); emu.stop(0)
  end
end,emu.eventType.endFrame)
emu.addMemoryCallback(function(address,value)
  if frame < cfg.trace_start or frame >= cfg.trace_end then return end
  local s=emu.getState()
  trace:write(string.format("%d %06X %04X %04X %04X %04X %02X %02X %04X\n",frame,address,s["cpu.a"],s["cpu.x"],s["cpu.y"],s["cpu.d"],s["cpu.ps"],s["cpu.dbr"],s["cpu.sp"]))
end,emu.callbackType.exec,0,0xFFFFFF)
